The output length is between 0 and 28 bytes.
""".
-doc #{group => "Hashing"}.
-spec sha3_224_hash(Input :: iodata(), OutputLen :: 0..28) -> binary().
sha3_224_hash(_Input, _OutputLen) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Finalize a `sha3_224` state and return between 0 and 28 digest bytes.
The original state remains reusable.
""".
-doc #{group => "Hashing"}.
-spec sha3_224_hash_final(State :: hash_state(), OutputLen :: 0..28) -> binary().
sha3_224_hash_final(_State, _OutputLen) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Create an immutable `sha3_224` hash state.
""".
-doc #{group => "Hashing"}.
-spec sha3_224_hash_init() -> hash_state().
sha3_224_hash_init() ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Absorb iodata into a `sha3_224` state and return a new state.
The original state remains reusable.
""".
-doc #{group => "Hashing"}.
-spec sha3_224_hash_update(State :: hash_state(), Input :: iodata()) -> hash_state().
sha3_224_hash_update(_State, _Input) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

