-doc """
Absorb iodata with `shake128` and return `OutputLen` output bytes.
""".
-doc #{group => "SHAKE"}.
-spec shake128_xof(Input :: iodata(), OutputLen :: non_neg_integer()) -> binary().
shake128_xof(_Input, _OutputLen) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Create an immutable `shake128` state in its absorbing phase.
""".
-doc #{group => "SHAKE"}.
-spec shake128_xof_init() -> xof_state().
shake128_xof_init() ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Squeeze `OutputLen` bytes and return the new `shake128` state with the bytes.
Continue squeezing from the returned state; the original state remains reusable.
""".
-doc #{group => "SHAKE"}.
-spec shake128_xof_output(State :: xof_state(), OutputLen :: non_neg_integer()) -> {xof_state(), binary()}.
shake128_xof_output(_State, _OutputLen) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Absorb iodata into a `shake128` state and return a new state.
Updates require a state that has not started squeezing output.
""".
-doc #{group => "SHAKE"}.
-spec shake128_xof_update(State :: xof_state(), Input :: iodata()) -> xof_state().
shake128_xof_update(_State, _Input) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

