-doc """
Initialize a sponge PRNG from seed bytes.
`Deterministic` selects the upstream PRNG's deterministic mode.
""".
-doc #{group => "Sponge PRNG"}.
-spec spongerng_csprng_init_from_buffer(Seed :: iodata(), Deterministic :: boolean()) -> spongerng_state().
spongerng_csprng_init_from_buffer(_Seed, _Deterministic) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Initialize a sponge PRNG using `/dev/urandom`.
Raise an exception if the entropy source cannot be read.
""".
-doc #{group => "Sponge PRNG"}.
-spec spongerng_csprng_init_from_dev_urandom() -> spongerng_state().
spongerng_csprng_init_from_dev_urandom() ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Initialize a sponge PRNG by reading `InputLen` bytes from a file.
`Filename` contains nonempty native filename bytes; file errors raise an exception.
""".
-doc #{group => "Sponge PRNG"}.
-spec spongerng_csprng_init_from_file(Filename :: iodata(), InputLen :: non_neg_integer(), Deterministic :: boolean()) ->
    spongerng_state().
spongerng_csprng_init_from_file(_Filename, _InputLen, _Deterministic) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Generate bytes and return the new PRNG state together with those bytes.
Continue with the returned state to advance the stream.
""".
-doc #{group => "Sponge PRNG"}.
-spec spongerng_csprng_next(State :: spongerng_state(), OutputLen :: non_neg_integer()) ->
    {spongerng_state(), binary()}.
spongerng_csprng_next(_State, _OutputLen) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Mix additional seed bytes into a PRNG state and return a new state.
""".
-doc #{group => "Sponge PRNG"}.
-spec spongerng_csprng_stir(State :: spongerng_state(), Input :: iodata()) -> spongerng_state().
spongerng_csprng_stir(_State, _Input) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Compute a Diffie-Hellman shared secret.
The public key comes first and the secret scalar second.
Return `error` when the upstream operation rejects the input, including low-order points.
""".
-doc #{group => "Diffie-Hellman"}.
-spec x25519(PublicKey :: x25519_public_key(), Scalar :: x25519_scalar()) -> x25519_shared_secret() | error.
x25519(_PublicKey, _Scalar) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
Derive an X25519 public key from a secret scalar.
""".
-doc #{group => "Diffie-Hellman"}.
-spec x25519_derive_public_key(Scalar :: x25519_scalar()) -> x25519_public_key().
x25519_derive_public_key(_Scalar) ->
    erlang:nif_error({nif_not_loaded, ?MODULE}).

-doc """
